struct MapNode {std::string id,name,owner,kind;double x,y;};
inline std::vector<MapNode> world_nodes(const json::object& snapshot){
    std::vector<MapNode> result;const auto& areas=array(snapshot,"areas");
    for(std::size_t a=0;a<std::min<std::size_t>(2,areas.size());++a)for(const auto* kind:{"capital","frontier","supply"})for(const auto& value:array(snapshot,"castles")){
        const auto& castle=value.as_object();if(text(castle,"area_id")!=text(areas[a].as_object(),"id")||text(castle,"kind")!=kind)continue;
        const bool frontier=std::string(kind)=="frontier";const double x=a?(frontier?318:428):(frontier?202:92);const double y=std::string(kind)=="capital"?70:frontier?155:240;
        result.push_back({text(castle,"id"),text(castle,"name"),text(castle,"owner_team_id"),kind,x,y});}
    return result;
}
inline std::pair<double,double> map_center(const std::vector<MapNode>& nodes,const std::string& selected,double zoom){
    if(zoom>1)for(const auto& node:nodes)if(node.id==selected)return {node.x,node.y};return {260,155};
}
inline int hit_world_map(const std::vector<MapNode>& nodes,const std::string& selected,double zoom,double x,double y){
    const auto center=map_center(nodes,selected,zoom);x=(x-260)/zoom+center.first;y=(y-155)/zoom+center.second;
    for(std::size_t n=0;n<nodes.size();++n)if(std::abs(x-nodes[n].x)<=54&&std::abs(y-nodes[n].y)<=32)return int(n);return -1;
}
inline std::string world_map_image(const json::object& snapshot,const std::string& team,const std::string& selected,double zoom){
    const std::string key=json::serialize(json::object{{"areas",array(snapshot,"areas")},{"castles",array(snapshot,"castles")},{"team",team},{"selected",selected},{"zoom",zoom}});
    static std::map<std::string,std::string> cache;if(const auto found=cache.find(key);found!=cache.end())return found->second;if(cache.size()>=12)cache.erase(cache.begin());
    const auto nodes=world_nodes(snapshot);const auto center=map_center(nodes,selected,zoom);
    auto image=emerald_chrome::raster(520,310,2,[&](cairo_t* c){
        cairo_set_source_rgb(c,.055,.14,.105);cairo_paint(c);cairo_save(c);cairo_translate(c,260,155);cairo_scale(c,zoom,zoom);cairo_translate(c,-center.first,-center.second);
        // The two geographical regions remain fixed when their owners change.
        for(int a=0;a<2;++a){const double x=a?350:35;cairo_set_source_rgba(c,.39,.51,.30,.10);cairo_move_to(c,x,26);cairo_line_to(c,x+130,25);cairo_line_to(c,x+160,150);cairo_line_to(c,x+130,278);cairo_line_to(c,x,282);cairo_line_to(c,x-20,155);cairo_close_path(c);cairo_fill_preserve(c);cairo_set_source_rgba(c,.73,.64,.36,.30);cairo_set_line_width(c,1);cairo_stroke(c);}
        for(const auto& source:nodes)for(const auto& castle:array(snapshot,"castles")){if(text(castle.as_object(),"id")!=source.id)continue;for(const auto& id:array(castle.as_object(),"neighbors"))if(id.is_string())for(const auto& target:nodes)if(target.id==std::string(id.as_string())&&source.id<target.id){const bool active=source.id==selected||target.id==selected;cairo_set_source_rgba(c,.84,.70,.38,active?.95:.45);cairo_set_line_width(c,active?3:1.8);cairo_move_to(c,source.x,source.y);cairo_line_to(c,target.x,target.y);cairo_stroke(c);}}
        auto label=[&](const std::string& value,double x,double y,double size,double maximum){cairo_select_font_face(c,"Lato",CAIRO_FONT_SLANT_NORMAL,CAIRO_FONT_WEIGHT_NORMAL);cairo_set_font_size(c,size);cairo_text_extents_t ext{};cairo_text_extents(c,value.c_str(),&ext);if(ext.width>maximum){cairo_set_font_size(c,size*maximum/ext.width);cairo_text_extents(c,value.c_str(),&ext);}cairo_move_to(c,x-ext.width/2-ext.x_bearing,y);cairo_show_text(c,value.c_str());};
        for(std::size_t a=0;a<std::min<std::size_t>(2,array(snapshot,"areas").size());++a){cairo_set_source_rgb(c,.89,.78,.50);label(text(array(snapshot,"areas")[a].as_object(),"name"),a?405:115,15,15,215);}
        for(const auto& node:nodes){const bool active=node.id==selected;const bool friendly=node.owner==team&&!team.empty();cairo_set_source_rgb(c,active?.87:.075,active?.78:.18,active?.54:.13);cairo_rectangle(c,node.x-54,node.y-32,108,64);cairo_fill_preserve(c);cairo_set_source_rgb(c,.88,.72,.38);cairo_set_line_width(c,active?2.8:1.6);cairo_stroke(c);
            cairo_set_source_rgb(c,active?.10:.88,active?.21:.76,active?.15:.45);cairo_set_line_width(c,1.6);cairo_move_to(c,node.x-9,node.y-11);cairo_line_to(c,node.x-9,node.y-24);cairo_line_to(c,node.x-5,node.y-24);cairo_line_to(c,node.x-5,node.y-20);cairo_line_to(c,node.x+5,node.y-20);cairo_line_to(c,node.x+5,node.y-24);cairo_line_to(c,node.x+9,node.y-24);cairo_line_to(c,node.x+9,node.y-11);cairo_close_path(c);cairo_stroke(c);label(node.name,node.x,node.y+6,14,98);label(node.owner.empty()?"Neutral":friendly?"Your team":"Opposing team",node.x,node.y+23,11,98);}
        cairo_restore(c);
    });return cache.emplace(key,std::move(image)).first->second;
}
inline int Workspace::map_hit(double x,double y)const{return hit_world_map(world_nodes(data("snapshot")),state_.selected[0],state_.zoom,x,y);}
