    const bool show_map=state_.tab==0&&state_.map;for(const auto* id:{"world_zoom_out","world_zoom_in","world_centre","world_map_canvas"})find_widget<gui2::widget>(id).set_visible(show_map?gui2::widget::visibility::visible:gui2::widget::visibility::invisible);auto& stack=find_widget<gui2::stacked_widget>("world_body_stack");stack.select_layer(show_map?0:1);find_widget<gui2::button>("world_map_toggle").set_visible(state_.tab==0?gui2::widget::visibility::visible:gui2::widget::visibility::invisible);find_widget<gui2::button>("world_map_toggle").set_label(state_.map?"List":"Map");if(state_.tab!=0)return;
