inline void Workspace::preferences(const json::object& soldier){if(data("catalog").empty()){start(false,"catalog",{},[this,soldier](const auto&){preferences(soldier);});return;}auto prefs=object(soldier,"advancement_preferences");std::vector<Card> nodes;std::set<std::string> visited;std::function<void(const std::string&)> visit=[&](const std::string& type){if(!visited.insert(type).second)return;for(const auto& value:array(data("catalog"),"troops")){const auto& node=value.as_object();if(text(node,"type")!=type)continue;if(array(node,"advances").size()>1)nodes.push_back({type,type,"Current choice: "+text(prefs,type.c_str(),std::string(array(node,"advances").front().as_string())),"Select the advancement used when computer defense promotes this soldier.",battle_unit_image(type,false),-1,node});for(const auto& next:array(node,"advances"))if(next.is_string())visit(std::string(next.as_string()));}};visit(text(soldier,"type"));const int node=pick("Advancement preferences",nodes,"Choose branch",nodes.empty()?"This soldier has no branching advancement ahead.":"The computer follows these choices during delegated defense.");if(node<0)return;std::vector<Card> branches;for(const auto& value:array(nodes[node].value,"advances")){const auto type=std::string(value.as_string());branches.push_back({type,type,"Native advancement","This choice applies when the soldier reaches this advancement.",battle_unit_image(type,false),-1,{}});}const int choice=pick("Choose advancement",branches,"Save preference");if(choice<0)return;prefs[nodes[node].id]=branches[choice].id;command("company_preferences",{{"expected_revision",number(data("company"),"revision")},{"soldier_id",text(soldier,"id")},{"preferences",prefs}});}
inline void Workspace::world_actions(){const auto& snapshot=data("snapshot");bool personal_defense=false;for(const auto& value:array(snapshot,"defenses"))if(text(value.as_object(),"owner_id")==hooks_.actor_id&&text(value.as_object(),"status")!="withdrawn")personal_defense=true;if(personal_defense)add("My standing defense",[this]{withdraw_personal_defense();});if(!flag(snapshot,"enrolled")){if(!team_id().empty()&&flag(object(snapshot,"capabilities"),"company"))add("Enter world",[this]{if(confirm_action("Enter the world","Enroll your company with your current team. It begins at your team's available homeland or recovery camp.","Enter world"))command("enroll");});else if(team_id().empty())add("Find a team",[this]{external("settings");});else add("Prepare company",[this]{state_.tab=1;render_content();refresh();});return;}const auto* selected_castle=selected();if(!selected_castle){add("Area wars",[this]{wars();});return;}const auto id=selected_castle->id;const auto& view=data("castle");const bool fresh=text(object(view,"castle"),"id")==id;
    if(!fresh){add("Inspect castle",[this,id]{start(false,"castle",{{"castle_id",id}});});return;}if(flag(view,"can_attack"))add("Plan attack",[this,id]{attack(id);});else if(flag(view,"can_offer_defense"))add("Offer defense",[this,id]{defense(id);});else add("View defenses",[this,id]{review_defenses(id);});
    add("Station company",[this,id]{if(confirm_action("Station company","Move your selected company to "+selected()->name+" along its approved route. This uses your movement order for this round.","Station"))command("station",{{"castle_id",id}});},flag(view,"can_station"),"No available route or company");add("Defense assignments",[this,id]{review_defenses(id);});if(flag(view,"can_govern"))add("Appoint governor",[this,id]{governor(id);});if(flag(view,"can_propose_development"))add("Propose Roadworks",[this,id]{if(confirm_action("Propose Roadworks","Ask your captain to approve Roadworks at this castle. This proposal does not spend Team Supply.","Send proposal"))command("roadworks_propose",{{"castle_id",id}});});if(flag(view,"can_develop"))add(object(selected_castle->value,"roadworks_proposal").empty()?"Build Roadworks":"Approve Roadworks",[this,id]{if(confirm_action("Build Roadworks","Spend 15 Team Supply. Roadworks allow one move across two friendly edges when this castle is the origin or destination. The building survives capture.","Build for 15"))command("roadworks",{{"castle_id",id}});},!flag(selected_castle->value,"roadworks"),"Roadworks already built");add("Area wars",[this]{wars();});}
inline void Workspace::withdraw_personal_defense(){std::vector<Card> rows;for(const auto& value:array(data("snapshot"),"defenses")){const auto& item=value.as_object();if(text(item,"owner_id")!=hooks_.actor_id||text(item,"status")=="withdrawn")continue;std::string castle="Castle defense";for(const auto& candidate:array(data("snapshot"),"castles"))if(text(candidate.as_object(),"id")==text(item,"castle_id"))castle=text(candidate.as_object(),"name");rows.push_back({text(item,"id"),castle,title(text(item,"status")),"Your standing company permission remains active until withdrawn. A committed engagement finishes before the company is released.","icons/helmet_bascinet.png",-1,item});}const int chosen=pick("My standing defense",rows,"Withdraw");if(chosen<0)return;if(confirm_action("Withdraw defense",rows[chosen].detail,"Withdraw"))command("defense_withdraw",{{"assignment_id",rows[chosen].id}});}
inline void Workspace::defense(const std::string& castle){if(data("company").empty()){start(false,"company",{},[this,castle](const auto&){defense(castle);});return;}const auto& force=object(data("company"),"warband");if(text(force,"hero_id").empty()){hint("Choose a company before offering defense.");return;}std::string description="Allow computer defense while you are away.\n\nHero: "+hero_name(text(force,"hero_id"))+"\nBracket: "+title(text(force,"bracket"))+"\nSoldiers: "+std::to_string(array(force,"soldier_ids").size());for(const auto& id:array(force,"soldier_ids"))if(id.is_string())for(const auto& value:array(data("company"),"soldiers")){const auto& soldier=value.as_object();if(text(soldier,"id")!=std::string(id.as_string()))continue;description+="\n• "+text(soldier,"type")+" · Level "+std::to_string(number(soldier,"level"))+" · XP "+std::to_string(number(soldier,"xp"));for(const auto& preference:object(soldier,"advancement_preferences"))if(preference.value().is_string())description+="\n  "+std::string(preference.key())+" → "+std::string(preference.value().as_string());}description+="\n\nThis exact company stays assigned until you withdraw. Your captain must approve it. Committed engagements finish before a withdrawal releases the company. Advancement preferences are retained; stronger forces need review.";if(!confirm_action("Standing castle defense",description,"Offer my company"))return;command("defense_offer",{{"castle_id",castle},{"bracket",text(force,"bracket","scout")}});}
inline void Workspace::review_defenses(const std::string& castle){const auto& view=data("castle");if(text(object(view,"castle"),"id")!=castle){start(false,"castle",{{"castle_id",castle}},[this,castle](const auto&){review_defenses(castle);});return;}std::vector<Card> assignments;for(const auto& value:array(view,"defenses")){const auto& assignment=value.as_object();assignments.push_back({text(assignment,"id"),text(assignment,"username","Company"),title(text(assignment,"status"))+" · "+title(text(assignment,"bracket")),"Standing computer defense\n\nOwner: "+text(assignment,"username")+"\nBracket: "+title(text(assignment,"bracket"))+"\nStatus: "+title(text(assignment,"status"))+"\n\nAssignment lasts until withdrawn. A locked company is released after its engagement.","icons/helmet_bascinet.png",-1,assignment});}const auto& capacity=object(view,"defense_capacity");const std::string capacity_notice=capacity.empty()?"":std::to_string(number(capacity,"approved"))+" / "+std::to_string(number(capacity,"limit",4))+" approved defense companies";const int choice=pick("Defense assignments",assignments,"Review",capacity_notice+(assignments.empty()?" · No assigned companies":""));if(choice<0)return;const auto& assignment=assignments[choice].value;const auto state=text(assignment,"status");if(text(assignment,"owner_id")==hooks_.actor_id&&state!="withdrawn"){if(confirm_action("Withdraw defense","Withdraw this standing assignment. If a battle already holds this company, withdrawal waits until it settles or is cancelled.","Withdraw"))command("defense_withdraw",{{"assignment_id",assignments[choice].id}});}else if(captain()&&flag(assignment,"can_approve")&&(state=="offered"||state=="needs_review")){if(confirm_action("Authorize castle defense",assignments[choice].detail+"\n\nAuthorize this member's offered company to defend the castle by computer.","Approve defense"))command("defense_approve",{{"assignment_id",assignments[choice].id}});}}
inline void Workspace::governor(const std::string& castle){std::vector<Card> candidates{{"","No governor","Remove appointment","The castle remains owned by your team.","icons/circlet_winged.png",-1,{}}};for(const auto& value:array(object(data("snapshot"),"team"),"members")){const auto& member=value.as_object();candidates.push_back({text(member,"id"),text(member,"username"),"Team member","Governors organize authorized defense and propose development. Personal troop consent and captain spending approval remain separate.","icons/helmet_bascinet.png",-1,member});}const int choice=pick("Appoint governor",candidates,"Appoint");if(choice<0)return;command("governor",{{"castle_id",castle},{"account_id",candidates[choice].id.empty()?json::value(nullptr):json::value(candidates[choice].id)}});}
inline void Workspace::attack(const std::string& castle){const auto& view=data("castle");std::vector<Card> origins;for(const auto& value:array(view,"eligible_origins")){const auto& origin=value.as_object();origins.push_back({text(origin,"id"),text(origin,"name"),"Legal attack origin","Your company attacks through this approved route. The target alone may change owner after a verified victory.","icons/terrain/terrain_type_castle.png",-1,origin});}const int origin=pick("Attack origin",origins,"Continue",origins.empty()?"Station an available company at an eligible origin first.":"");if(origin<0)return;std::vector<Card> brackets{{"scout","Scout","120 points","Hero tier up to 2 · Soldiers tier 1 · Effective hero level cap 5","icons/helmet_bascinet.png",-1,{}},{"veteran","Veteran","240 points","Hero tier up to 3 · Soldiers tier up to 3 · Effective hero level cap 15","icons/helmet_bascinet.png",-1,{}},{"champion","Champion","420 points","Hero tier up to 5 · Soldiers tier up to 4 · Effective hero level cap 30","icons/helmet_bascinet.png",-1,{}}};const int bracket=pick("Battle bracket",brackets,"Review attack");if(bracket<0)return;if(!confirm_action("Publish castle contest","Origin: "+origins[origin].name+"\nTarget: "+text(object(view,"castle"),"name")+"\nBracket: "+brackets[bracket].name+"\n\nThis publishes a proposal. Required approvals, personal Ready and the host's tactical window must follow. No land changes by publishing.","Publish attack"))return;json::object proposal{{"origin_id",origins[origin].id},{"target_id",castle},{"bracket",brackets[bracket].id}};if(!text(object(view,"castle"),"owner_team_id").empty()){for(const auto& value:array(data("snapshot"),"wars")){const auto& war=value.as_object();if(text(war,"state")!="active")continue;for(const auto& target:array(war,"target_ids"))if(target.is_string()&&std::string(target.as_string())==castle)proposal["war_id"]=text(war,"id");}if(!proposal.if_contains("war_id")){hint("Both captains must approve an Area war for this target first.");return;}}command("attack",std::move(proposal),[this](const auto& result){state_.tab=2;state_.selected[2]=text(object(result,"battle"),"id");});}
inline void Workspace::wars(){
    const auto& snapshot=data("snapshot");
    auto castle_name=[&](const std::string& id){for(const auto& value:array(snapshot,"castles"))if(text(value.as_object(),"id")==id)return text(value.as_object(),"name");return std::string("Historical castle");};
    auto team_name=[&](const std::string& id){for(const auto& value:array(snapshot,"teams"))if(text(value.as_object(),"id")==id)return text(value.as_object(),"name");return std::string("Historical team");};
    std::vector<Card> cards;
    for(const auto& value:array(snapshot,"wars")){const auto& war=value.as_object();std::string heading="Area war",detail="Status: "+title(text(war,"state"));
        for(const auto& id:array(war,"team_ids"))if(id.is_string())detail+="\n"+team_name(std::string(id.as_string()));
        detail+="\n\nObjectives";for(const auto& id:array(war,"target_ids"))if(id.is_string())detail+="\n• "+castle_name(std::string(id.as_string()));
        detail+="\n\nRounds "+std::to_string(number(war,"start_round"))+"–"+std::to_string(number(war,"end_round"))+". Each castle settles independently. Unplayed land never transfers.";
        const auto& result=object(war,"result");if(!result.empty()){detail+="\n\n"+title(text(result,"outcome"));if(!text(result,"winner_team_id").empty())detail+="\nWinner: "+team_name(text(result,"winner_team_id"));if(!text(result,"title").empty())detail+="\n"+text(result,"title");}
        cards.push_back({text(war,"id"),heading,title(text(war,"state")),detail,"icons/circlet_winged.png",-1,war});}
    if(captain())cards.push_back({"new","Propose Area war","Choose opponent and objectives","Both captains approve the bounded campaign. Global round timing stays under the host's control.","icons/crossed_sword_and_hammer.png",-1,{}});
    const int choice=pick("Area wars",cards,"Review",cards.empty()?"No Area wars have been proposed.":"");if(choice<0)return;
    if(cards[choice].id!="new"){
        const auto& war=cards[choice].value;const auto state=text(war,"state");bool participating=false,approved=false;
        for(const auto& id:array(war,"team_ids"))if(id.is_string()&&std::string(id.as_string())==team_id())participating=true;
        for(const auto& id:array(war,"approvals"))if(id.is_string()&&std::string(id.as_string())==team_id())approved=true;
        if(!captain()||!participating||state!="proposed")return;
        std::vector<Card> choices;if(!approved)choices.push_back({"approve","Approve agreement","Accept these objectives",cards[choice].detail,"icons/circlet_winged.png",-1,{}});
        choices.push_back({"cancel",approved?"Withdraw proposal":"Decline proposal","Keep existing territory and history",cards[choice].detail,"icons/crossed_sword_and_hammer.png",-1,{}});
        const int action=pick("War proposal",choices,"Continue");if(action<0)return;
        if(choices[action].id=="approve"){if(confirm_action("Approve Area war",cards[choice].detail,"Approve agreement"))command("war_approve",{{"war_id",cards[choice].id}});}
        else if(confirm_action(choices[action].name,"Cancel this proposed war agreement. Existing territory and historical battles stay unchanged. An active war cannot be cancelled here.",choices[action].name))command("war_cancel",{{"war_id",cards[choice].id}});
        return;
    }
    std::vector<Card> teams;for(const auto& value:array(snapshot,"teams")){const auto& team=value.as_object();if(text(team,"id")==team_id())continue;teams.push_back({text(team,"id"),text(team,"name"),"Opposing team","This captain must approve the proposed war.","icons/circlet_winged.png",-1,team});}
    const int opponent=pick("Choose opposing team",teams);if(opponent<0)return;
    WarDraft draft;if(!sheet([&]{ObjectiveEditor editor(snapshot,draft);return editor.show();}))return;
    json::array targets;std::string names;for(const auto& id:draft.targets){targets.emplace_back(id);names+="\n• "+castle_name(id);}
    std::string area="None";for(const auto& value:array(snapshot,"areas"))if(text(value.as_object(),"id")==draft.area)area=text(value.as_object(),"name");
    if(!confirm_action("Propose Area war",teams[opponent].name+"\nArea objective: "+area+"\nTargets:"+names+"\n\nMaximum three global rounds. One attacking engagement per team per round. Captains approve before commitment.","Propose war"))return;
    command("war_propose",{{"opponent_team_id",teams[opponent].id},{"target_ids",targets},{"objective_area_id",draft.area.empty()?json::value(nullptr):json::value(draft.area)}});
}
inline void Workspace::open_run(const json::object& battle,bool replay){const auto id=text(battle,"id");const auto state=text(battle,"state");if(id.empty())return;if(!replay&&state!="preparing"&&state!="running"&&state!="paused"){hint(state=="queued"?"Waiting for the battle worker. Your place is saved.":"Waiting for the tactical window and required consent.");return;}if(hooks_.launch){hooks_.launch(id,replay);set_retval(gui2::retval::OK);}}
inline void Workspace::battle_actions(){const auto* card=selected();if(card){const auto id=card->id;const auto& view=data("battle");const bool fresh=text(object(view,"battle"),"id")==id;const auto battle=fresh?object(view,"battle"):card->value;const auto state=text(battle,"state");const bool mine=std::any_of(array(battle,"armies").begin(),array(battle,"armies").end(),[this](const auto& v){return text(v.as_object(),"account_id")==hooks_.actor_id&&text(v.as_object(),"controller")=="human";});
        if(state=="awaiting_confirmation"&&fresh&&flag(view,"can_confirm"))add("Confirm result",[this,id]{if(confirm_action("Confirm company result",selected()->detail+"\n\nConfirm the recorded native outcome. Both captains must confirm before permanent rewards settle.","Confirm result"))command("battle_confirm",{{"run_id",id}});});else if(state=="completed"||state=="settled")add("Watch replay",[this,battle]{open_run(battle,true);});else if((state=="preparing"||state=="running"||state=="paused")&&mine)add(state=="preparing"?"Enter battle":"Resume battle",[this,battle]{open_run(battle);});else if(fresh&&state=="draft"&&flag(view,"can_ready")){bool ready=false;for(const auto& army:array(battle,"armies"))if(text(army.as_object(),"account_id")==hooks_.actor_id)ready=flag(army.as_object(),"ready");add(ready?"Not ready":"Ready",[this,id,ready]{if(ready||confirm_action("Ready company",selected()->detail+"\n\nConfirm this company and the current battle settings. Material changes require fresh consent.","Ready"))command("battle_ready",{{"run_id",id},{"ready",!ready}});});}
        else if(fresh&&state=="draft"&&flag(view,"can_join"))add("Join with my company",[this,id]{if(confirm_action("Join battle",selected()->detail+"\n\nJoin using your selected company. You will review the force before Ready.","Join"))command("battle_join",{{"run_id",id},{"team_id",team_id()}});});else add("Refresh battle",[this,id]{start(false,"battle",{{"run_id",id}});});
        if(fresh&&state=="draft"&&flag(view,"can_approve"))add("Approve agreement",[this,id]{if(confirm_action("Approve battle",selected()->detail+"\n\nApprove these current forces, rules and stakes for your team.","Approve"))command("battle_approve",{{"run_id",id}});});if(fresh&&(state=="draft"||state=="queued"||state=="preparing")&&flag(view,"can_cancel"))add("Cancel proposal",[this,id]{if(confirm_action("Cancel proposal","Cancel this proposal and release its eligible commitments. An active battle cannot be cancelled here.","Cancel proposal"))command("battle_cancel",{{"run_id",id}});});}
    add("Skirmishes",[this]{external(state_.tab==3?"legacy_history":"skirmishes");});if(state_.tab==2){add("New skirmish",[this]{external("new_skirmish");},captain(),"Only your captain creates a skirmish");add("Company expeditions",[this]{expedition();});}if(state_.tab==3&&!state_.history_before.empty())add("Latest history",[this]{state_.history_before.clear();refresh_tab();});if(state_.tab==3&&!text(data("history"),"next_before").empty())add("Older history",[this]{state_.history_before=text(data("history"),"next_before");refresh_tab();});}
inline void show(Hooks hooks,State& state){Workspace dialog(std::move(hooks),state);dialog.show();}
